                                                   uint32_t aIndex,
                                                   ErrorResult& aRv) {
  if (aIndex > mAdoptedStyleSheets.Length()) [[unlikely]] {
    MOZ_ASSERT_UNREACHABLE("Out of sync proxy");
    return;
  }
  Document& doc = *AsNode().OwnerDoc();
